};

export type StrokeFrame = { origin: Point; scale: number; points: StrokePoint[] };

// Path2D keeps float32, so points live relative to the stroke bbox, never the tile.
export const strokeFrame = (tile: Tile, stroke: Stroke): StrokeFrame => {
  const { bbox } = stroke;
  const origin = { x: bbox.minX, y: bbox.minY };
  const extent = Math.max(
    bbox.maxX - bbox.minX,
    bbox.maxY - bbox.minY,
    strokeWorldWidth(stroke.size, stroke.nativeZoom),
  );
  const scale = extent / TILE_SIZE;
  const points = stroke.points.map(([x, y, pressure]): StrokePoint => {
    const world = fromTileLocal(tile, { x, y });
    return [(world.x - origin.x) / scale, (world.y - origin.y) / scale, pressure];
  });
  return { origin, scale, points };
};

export const strokeFramePath = (stroke: Stroke, frame: StrokeFrame): Path2D =>
  outlinePath(frame.points, strokeWorldWidth(stroke.size, stroke.nativeZoom) / frame.scale, true);

export const draftScreenPath = (
  draft: Pick<Draft, "size" | "nativeZoom" | "points">,
  toScreen: (world: Point) => Point,
  zoom: number,
): Path2D =>
  outlinePath(
    draft.points.map(([x, y, pressure]) => {
      const screen = toScreen({ x, y });
      return [screen.x, screen.y, pressure];
    }),
    strokeWorldWidth(draft.size, draft.nativeZoom) * zoom,
    false,
  );

export const translateStroke = (
  tile: Tile,
  stroke: Stroke,
  dx: number,
  dy: number,
): StoredObject | undefined => {
  const bbox = {
    minX: stroke.bbox.minX + dx,
    minY: stroke.bbox.minY + dy,
    maxX: stroke.bbox.maxX + dx,
    maxY: stroke.bbox.maxY + dy,
  };
  const placed = place(bbox);
  if (!placed.ok) return undefined;
  const points = stroke.points.map(([x, y, pressure]): StrokePoint => {
    const world = fromTileLocal(tile, { x, y });
    const local = toTileLocal(placed.tile, { x: world.x + dx, y: world.y + dy });
    return [local.x, local.y, pressure];
  });
  return { tile: placed.tile, object: { ...stroke, bbox, points } };
};
import type { Camera } from "./camera";

export type Viewport = { x: number; y: number; zoom: number };

export type Peer = { clientId: number; name: string; colour: string; self: boolean };

export type PeerState = Peer & { viewport: Viewport | undefined };

export type Presence = { peers: readonly Peer[]; following: number | undefined };

export const GUEST = "Guest";

export const PRESENCE_THROTTLE_MS = 100;

export const displayName = (identity: unknown): string => {
  if (typeof identity !== "string") return GUEST;
  const trimmed = identity.trim();
  if (trimmed === "") return GUEST;
  const at = trimmed.indexOf("@");
  if (at === -1) return trimmed;
  return at === 0 ? GUEST : trimmed.slice(0, at);
};

export const presenceColour = (clientId: number): string =>
  `hsl(${Math.round((clientId * 137.508) % 360)} 70% 42%)`;

export const viewportOf = (camera: Camera, width: number, height: number): Viewport => ({
  x: camera.x + width / 2 / camera.zoom,
  y: camera.y + height / 2 / camera.zoom,
  zoom: camera.zoom,
});

export const cameraFor = (viewport: Viewport, width: number, height: number): Camera => ({
  x: viewport.x - width / 2 / viewport.zoom,
  y: viewport.y - height / 2 / viewport.zoom,
  zoom: viewport.zoom,
});

const isViewport = (value: unknown): value is Viewport => {
  if (typeof value !== "object" || value === null) return false;
  const { x, y, zoom } = value as Record<string, unknown>;
  return (
    typeof x === "number" &&
    typeof y === "number" &&
    typeof zoom === "number" &&
    Number.isFinite(x) &&
    Number.isFinite(y) &&
    Number.isFinite(zoom) &&
    zoom > 0
  );
};

const field = (value: unknown, key: string): unknown =>
  typeof value === "object" && value !== null ? (value as Record<string, unknown>)[key] : undefined;

export const peerOf = (clientId: number, state: unknown, selfId: number): PeerState => {
  const self = clientId === selfId;
  const viewport = field(field(state, "presence"), "viewport");
  return {
    clientId,
    name: self ? "You" : displayName(field(field(state, "user"), "name")),
    colour: presenceColour(clientId),
    self,
    viewport: isViewport(viewport) ? viewport : undefined,
  };
};

export const peersOf = (states: ReadonlyMap<number, unknown>, selfId: number): PeerState[] =>
  [...states]
    .map(([clientId, state]) => peerOf(clientId, state, selfId))
    .sort((a, b) => Number(b.self) - Number(a.self) || a.clientId - b.clientId);

export const samePresence = (a: Presence, b: Presence): boolean =>
  a.following === b.following &&
  a.peers.length === b.peers.length &&
  a.peers.every(
    (peer, index) =>
      peer.clientId === b.peers[index]?.clientId &&
      peer.name === b.peers[index]?.name &&
      peer.self === b.peers[index]?.self,
  );
import type { StoredObject } from "@stallion/client-store";
import type {
  BoardLock,
  BoardOptions,
  BoardStatus,
  History,
  LiveObjects,
  PinResult,
  PinState,
  SetPinResult,
  StallionBoard,
} from "@stallion/client-sync";
import type { BBox } from "@stallion/geometry";
import { errorMessage } from "./report";

export type Connection = "Connected" | "Reconnecting" | "Offline" | "Locked" | "LocalOnly";

export const CONNECTION_LABEL: Record<Connection, string> = {
  Connected: "Connected",
  Reconnecting: "Reconnecting",
  Offline: "Offline",
  Locked: "Locked: enter the board PIN to join",
  LocalOnly: "Local only: strokes stay in this browser",
};

export const VIEW_DEBOUNCE_MS = 100;

export type Awareness = StallionBoard["awareness"];

export type DrawingSource = {
  view(viewport: BBox, zoom: number): void;
  commit(stored: StoredObject): void;
  erase(objectId: string): void;
  readonly objects: LiveObjects;
  readonly history: History;
  readonly awareness: Awareness | undefined;
  close(): Promise<void>;
};

export type BoardSource = DrawingSource & {
  readonly lock: BoardLock | undefined;
  join(pin: string): Promise<PinResult>;
  setPin(pin: string): Promise<SetPinResult>;
  pinState(): Promise<PinState>;
};

export type OpenBoard = (url: string, boardId: string, options?: BoardOptions) => StallionBoard;

export type SourceOptions = {
  url: string | undefined;
  boardId: string;
  openBoard: OpenBoard;
  onConnection: (connection: Connection) => void;
  onError: (message: string) => void;
};

export const connectionFor = (status: BoardStatus, online: boolean): Connection => {
  if (status === "Open") return "Connected";
  if (status === "NeedsPin") return "Locked";
  if (!online) return "Offline";
  return status === "Closed" ? "Offline" : "Reconnecting";
};

const debounced = (run: (viewport: BBox, zoom: number) => void) => {
  let timer: ReturnType<typeof setTimeout> | undefined;
  return {
    call(viewport: BBox, zoom: number): void {
      clearTimeout(timer);
      timer = setTimeout(() => run(viewport, zoom), VIEW_DEBOUNCE_MS);
    },
    cancel(): void {
      clearTimeout(timer);
    },
  };
};

export function openLocalSource(options: SourceOptions): BoardSource {
  const board = options.openBoard("", options.boardId, {
    localOnly: true,
    cache: { cap: Number.POSITIVE_INFINITY },
    onError: ({ reason }) => options.onError(reason),
  });
  const setView = debounced((viewport, zoom) => board.setView(viewport, zoom));
  return {
    view: setView.call,
    commit: (stored) => board.put(stored),
    erase: (objectId) => board.remove(objectId),
    objects: board.objects,
    history: board.history,
    awareness: undefined,
    get lock() {
      return board.lock;
    },
    join: (pin) => board.join(pin),
    setPin: (pin) => board.setPin(pin),
    pinState: () => board.pinState(),
    close() {
      setView.cancel();
      return board.close();
    },
  };
}

export function openSyncSource(url: string, options: SourceOptions): BoardSource {
  const online = () => globalThis.navigator?.onLine !== false;
  const board = options.openBoard(url, options.boardId, {
    onStatus: (status) => options.onConnection(connectionFor(status, online())),
    onError: ({ tileKey, reason }) =>
      options.onError(`Sync failed${tileKey ? ` on tile ${tileKey}` : ""}: ${reason}`),
  });
  options.onConnection(connectionFor(board.status, online()));
  const setView = debounced((viewport, zoom) => board.setView(viewport, zoom));
  return {
    view: setView.call,
    commit: (stored) => board.put(stored),
    erase: (objectId) => board.remove(objectId),
    objects: board.objects,
    history: board.history,
    awareness: board.awareness,
    get lock() {
      return board.lock;
    },
    join: (pin) => board.join(pin),
    setPin: (pin) => board.setPin(pin),
    pinState: () => board.pinState(),
    close() {
      setView.cancel();
      return board.close();
    },
  };
}

export function openSource(options: SourceOptions): BoardSource {
  if (!options.url) {
    options.onConnection("LocalOnly");
    return openLocalSource(options);
  }
  try {
    return openSyncSource(options.url, options);
  } catch (error) {
    options.onError(
      `Could not connect to ${options.url} (${errorMessage(error)}), working local only`,
    );
    options.onConnection("LocalOnly");
    return openLocalSource(options);
  }
}

const PRIVATE_HOST = [
  /^localhost$/,
  /\.localhost$/,
  /\.ts\.net$/,
  /^\[?::1\]?$/,
  /^127\./,
  /^10\./,
  /^192\.168\./,
  /^172\.(1[6-9]|2\d|3[01])\./,
  /^100\.(6[4-9]|[7-9]\d|1[01]\d|12[0-7])\./,
];

export const syncUrlFor = (
  configured: string | undefined,
  location: Pick<Location, "protocol" | "host" | "hostname">,
): string | undefined => {
  if (configured) return configured;
  if (PRIVATE_HOST.some((pattern) => pattern.test(location.hostname))) return undefined;
  return `${location.protocol === "https:" ? "wss" : "ws"}://${location.host}`;
};

