import { mkdirSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { createRequire } from "node:module";

const WT = join(homedir(), "development", "stallion-worktrees", "stale");
const require = createRequire(join(WT, "package.json"));
const { chromium } = require("playwright");
const Y = require("yjs");
const { accessHeaders } = await import(join(WT, "npm-scripts", "env.mjs"));

const ORIGIN = process.argv[2] ?? "https://stallion.matthijs-f49.workers.dev";
const LABEL = process.argv[3] ?? "before";
const RUNS = Number(process.argv[4] ?? 6);
const ONLY = process.argv[5] ? process.argv[5].split(",").map(Number) : [1, 2, 3, 4, 5];
const OUT = join(homedir(), "development", ".tmp", "stallion-stale", LABEL);
mkdirSync(OUT, { recursive: true });

const VIEWPORT = { width: 1280, height: 800 };
const BLUE = { label: "Colour 5", rgb: [0x00, 0x90, 0xff] };
const RED = { label: "Colour 2", rgb: [0xe5, 0x48, 0x4d] };
const STEP_MS = 12;
const SETTLE_MS = 3500;
const PIXEL_TOLERANCE = 0.05;

const boardId = () => {
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  let v = 0n;
  for (const b of bytes) v = (v << 8n) | BigInt(b);
  return v.toString(36).padStart(25, "0");
};

const line = (x0, y0, x1, y1, n = 40) =>
  Array.from({ length: n + 1 }, (_, i) => ({ x: x0 + ((x1 - x0) * i) / n, y: y0 + ((y1 - y0) * i) / n + Math.sin(i / 3) * 6 }));

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const browser = await chromium.launch({ headless: true });

const openSide = async (name, url, touch, colour) => {
  const context = await browser.newContext({ viewport: VIEWPORT, hasTouch: touch, extraHTTPHeaders: accessHeaders() });
  const page = await context.newPage();
  const side = { name, context, page, touch, errors: [], frames: { sent: 0, received: 0 }, colour };
  page.on("console", (m) => { if (m.type() === "error") side.errors.push(m.text()); });
  page.on("pageerror", (e) => side.errors.push(`pageerror: ${e.message}`));
  page.on("websocket", (ws) => {
    ws.on("framesent", () => side.frames.sent++);
    ws.on("framereceived", () => side.frames.received++);
  });
  await page.goto(url, { waitUntil: "load" });
  await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 20000 });
  await page.locator('.status[data-connection="Connected"]').waitFor({ timeout: 20000 });
  if (colour) {
    await page.getByRole("button", { name: "Large pencil" }).click();
    await page.getByRole("button", { name: colour.label, exact: true }).click();
  }
  if (touch) side.cdp = await context.newCDPSession(page);
  return side;
};

const setMode = async (side, mode) => {
  const eraser = side.page.getByRole("button", { name: "Eraser", exact: true });
  const pressed = (await eraser.getAttribute("aria-pressed")) === "true";
  if ((mode === "Eraser") !== pressed) await eraser.click();
};

const gesture = async (side, points) => {
  const [first, ...rest] = points;
  if (side.touch) {
    const t = (type, p) => side.cdp.send("Input.dispatchTouchEvent", { type, touchPoints: p ? [{ x: p.x, y: p.y, id: 1, radiusX: 2, radiusY: 2 }] : [] });
    await t("touchStart", first);
    await sleep(80);
    for (const p of rest) { await t("touchMove", p); await sleep(STEP_MS); }
    await t("touchEnd");
    return;
  }
  await side.page.mouse.move(first.x, first.y);
  await side.page.mouse.down();
  for (const p of rest) { await side.page.mouse.move(p.x, p.y); await sleep(STEP_MS); }
  await side.page.mouse.up();
};

const draw = async (side, points) => { await setMode(side, "Pencil"); await gesture(side, points); };
const erase = async (side, points) => { await setMode(side, "Eraser"); await gesture(side, points); };

const pixels = (page) => page.evaluate(([colours]) => {
  const canvas = document.querySelector("canvas.surface");
  const ctx = canvas.getContext("2d");
  const { data } = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const counts = colours.map(() => 0);
  for (let i = 0; i < data.length; i += 4) {
    colours.forEach(([r, g, b], k) => {
      if (data[i + 3] > 200 && Math.abs(data[i] - r) + Math.abs(data[i + 1] - g) + Math.abs(data[i + 2] - b) < 60) counts[k]++;
    });
  }
  return { blue: counts[0], red: counts[1] };
}, [[BLUE.rgb, RED.rgb]]);

const tileStates = (page, id) => page.evaluate((id) => new Promise((resolve, reject) => {
  const req = indexedDB.open("stallion");
  req.onerror = () => reject(req.error);
  req.onsuccess = () => {
    const db = req.result;
    if (![...db.objectStoreNames].includes("tiles")) { db.close(); resolve([]); return; }
    const all = db.transaction("tiles", "readonly").objectStore("tiles").getAll();
    all.onsuccess = () => {
      db.close();
      resolve(all.result.filter((r) => r.boardId === id).map((r) => ({ key: `${r.level}:${r.tx}:${r.ty}`, state: Array.from(r.state) })));
    };
  };
}), id);

const objectIds = async (page, id) => {
  const ids = [];
  for (const { key, state } of await tileStates(page, id)) {
    const doc = new Y.Doc();
    Y.applyUpdate(doc, Uint8Array.from(state));
    for (const objectId of doc.getMap("objects").keys()) ids.push(`${key}/${objectId.slice(-6)}`);
  }
  return ids.sort();
};

const observe = async (side, id) => ({ px: await pixels(side.page), ids: await objectIds(side.page, id), status: await side.page.locator(".status[data-connection]").getAttribute("data-connection") });

const close = (a, b) => Math.abs(a - b) <= Math.max(150, PIXEL_TOLERANCE * Math.max(a, b));

const scenarios = {
  1: async (A, B) => {
    await draw(A, line(150, 200, 550, 220));
    await sleep(1500);
    await Promise.all([draw(A, line(150, 500, 550, 520, 120)), (async () => { await sleep(300); await erase(B, line(350, 150, 350, 280, 20)); })()]);
  },
  2: async (A, B) => {
    await Promise.all([
      (async () => { for (let i = 0; i < 4; i++) { await draw(A, line(100, 120 + i * 60, 450, 130 + i * 60, 20)); await sleep(150); } })(),
