    for (let i = 0; i < 6; i++) { await B.page.mouse.wheel(0, -400); await sleep(60); }
  },
  4: async (A, B) => {
    await draw(A, line(900, 300, 1150, 330));
    await sleep(1500);
    await Promise.all([draw(A, line(150, 500, 550, 520, 120)), (async () => { await sleep(300); await erase(B, line(1024, 250, 1024, 380, 20)); })()]);
  },
  5: async (A, B) => {
    await draw(A, line(150, 300, 550, 320));
    await sleep(2000);
    await A.context.setOffline(true);
    await sleep(500);
    await erase(B, line(350, 250, 350, 380, 20));
    await sleep(4500);
    A.offlineStatus = await A.page.locator(".status[data-connection]").getAttribute("data-connection");
    await A.context.setOffline(false);
    await A.page.locator('.status[data-connection="Connected"]').waitFor({ timeout: 30000 }).catch(() => undefined);
  },
};

const results = [];
for (const n of ONLY) {
  for (let run = 1; run <= RUNS; run++) {
    const touch = run % 2 === 0;
    const id = boardId();
    const url = `${ORIGIN}/b/${id}`;
