    const a = await observe(A, id);
    const b = await observe(B, id);
    const C = await openSide("C", url, false, undefined);
    await sleep(SETTLE_MS);
    const c = await observe(C, id);
    const mismatches = [];
    for (const colour of ["blue", "red"]) {
