import * as Y from "yjs";
import type { Fetch } from "./pin";
import type { Connect, SocketHandlers } from "./socket";

type Session = {
  handlers: SocketHandlers;
  tiles: Set<string>;
  view: ViewTiles | undefined;
  received: Frame[];
};

const OBJECTS = "objects";

